  1	// src/lib/rechner/projektbewertung.js
  2	//
  3	// Orientierende Bewertung von Solarprojekten (Projektrechte) nach Phase –
  4	// reine Logik. Ausgangspunkt sind die Marktspannen je Entwicklungsstand aus
  5	// PHASEN (src/lib/invest/markt.js). Werttreiber und -minderer verschieben die
  6	// Spanne. Ergebnis ist eine Einordnung für ein erstes Gespräch, kein Gutachten:
  7	// Den tatsächlichen Preis bestimmen Due Diligence, Verhandlung und Wettbewerb.
  8	
  9	import { PHASEN, phaseById, FREIFLAECHE, ERLOESE } from "../invest/markt.js";
 10	
 11	export const LAENDER = [
 12	  { id: "DE", label: "Deutschland" },
 13	  { id: "AT", label: "Österreich" },
 14	  { id: "CH", label: "Schweiz" },
 15	];
 16	
 17	export const NETZSTATUS = [
 18	  { id: "offen", label: "Noch offen", sub: "keine Anfrage/Zusage" },
 19	  { id: "anfrage", label: "Angefragt", sub: "Netzprüfung läuft" },
 20	  { id: "zusage", label: "Zusage", sub: "Einspeisepunkt benannt" },
 21	  { id: "reserviert", label: "Reserviert", sub: "Kapazität vertraglich" },
 22	];
 23	
 24	export const VERMARKTUNG = [
 25	  { id: "keine", label: "Offen" },
 26	  { id: "eeg", label: "EEG-Zuschlag" },
 27	  { id: "ppa", label: "PPA unterschrieben" },
 28	];
 29	
 30	export const STANDARD = { mwp: 10, phase: "satzung", netz: "zusage", netzKm: 1.5, vermarktung: "keine", land: "DE" };
 31	
 32	const idx = (id) => PHASEN.findIndex((p) => p.id === id);
 33	
 34	/**
 35	 * @returns {{ phase, preisKwp:{min,mittel,max}, gesamt:{min,mittel,max}, risiko, risikoStufe, treiber:[], minderer:[], hinweise:[], monateBisRtb }}
 36	 */
 37	export function bewerteProjekt(eingabe = {}) {
 38	  const e = { ...STANDARD, ...eingabe };
 39	  const phase = phaseById(e.phase);
 40	  const pi = idx(phase.id);
 41	  const bestand = phase.id === "cod";
 42	  const kwp = e.mwp * 1000;
 43	
 44	  let { min, max } = phase.preisProKwp;
 45	  const treiber = [];
 46	  const minderer = [];
 47	  const hinweise = [];
 48	  let risikoStufe = pi <= 0 ? 5 : pi === 1 ? 4 : pi === 2 ? 3 : pi === 3 ? 2 : 1; // 5 sehr hoch … 0 sehr gering
 49	  if (bestand) risikoStufe = 0;
 50	
 51	  // Faktoren multiplizieren die Spanne, Abzüge (€/kWp) verschieben sie
 52	  let faktor = 1;
 53	  let abzug = 0;
 54	
 55	  /* --- Netzanschluss ------------------------------------------------ */
 56	  if (!bestand) {
 57	    const netzPhase = idx("netz");
 58	    if (e.netz === "reserviert") {
 59	      faktor *= 1.1;
 60	      treiber.push("Netzkapazität vertraglich reserviert – der größte Engpass im Markt ist gelöst.");
 61	      if (pi < netzPhase) risikoStufe -= 1;
 62	    } else if (e.netz === "zusage") {
 63	      if (pi < netzPhase) {
 64	        faktor *= 1.25;
 65	        risikoStufe -= 1;
 66	        treiber.push("Netzzusage liegt schon vor der üblichen Phase vor – deutlicher Wertsprung.");
 67	      } else {
 68	        treiber.push("Netzzusage mit benanntem Einspeisepunkt.");
 69	      }
 70	    } else if (e.netz === "anfrage") {
 71	      if (pi >= netzPhase) {
 72	        faktor *= 0.7;
 73	        risikoStufe += 1;
 74	        minderer.push("Für diese Phase fehlt die Netzzusage noch – Käufer preisen Verzögerung und Kosten ein.");
 75	      } else {
 76	        hinweise.push("Netzanfrage gestellt: Mit der Zusage steigt der Wert typischerweise spürbar.");
 77	      }
 78	    } else {
 79	      if (pi >= netzPhase) {
 80	        faktor *= 0.5;
 81	        risikoStufe += 2;
 82	        minderer.push("Ohne Netzanfrage ist der Anschluss das zentrale Risiko – viele Käufer steigen erst mit Zusage ein.");
 83	      } else {
 84	        minderer.push("Netzanschluss noch nicht angefragt – in vielen Regionen der Engpass Nummer eins.");
 85	      }
 86	    }
 87	
 88	    // Kabeltrasse: Mehrkosten gegenüber ~1 km Standard mindern den Wert direkt
 89	    const mehrKm = Math.max(0, e.netzKm - 1);
 90	    if (mehrKm > 0) {
 91	      abzug += (mehrKm * 1000 * FREIFLAECHE.kabelProMeter) / kwp;
 92	      const eurKwp = Math.round((mehrKm * 1000 * FREIFLAECHE.kabelProMeter) / kwp);
 93	      if (eurKwp >= 5) minderer.push(`Kabeltrasse ${String(e.netzKm).replace(".", ",")} km: rund ${eurKwp} €/kWp Mehrkosten für den Käufer.`);
 94	    } else {
 95	      treiber.push("Einspeisepunkt in unmittelbarer Nähe – geringe Anschlusskosten.");
 96	    }
 97	    if (e.netzKm > 8) {
 98	      risikoStufe += 1;
 99	      minderer.push("Lange Trasse bedeutet zusätzliche Wegerechte und Genehmigungen.");
100	    }
101	  }
102	
103	  /* --- Größe ----------------------------------------------------------- */
104	  if (e.mwp < 3) {
105	    faktor *= 0.75;
106	    minderer.push("Unter 3 MWp: Fixkosten für Netz, Gutachten und Due Diligence verteilen sich auf wenig Leistung – kleinerer Käuferkreis.");
107	  } else if (e.mwp < 8) {
108	    faktor *= 0.9;
109	    minderer.push("Unter 8 MWp: für institutionelle Käufer oft unter der Mindestgröße.");
110	  } else if (e.mwp >= 50) {
111	    faktor *= 1.12;
112	    treiber.push("Ab 50 MWp: interessant für institutionelle Investoren und Portfoliokäufer.");
113	  } else if (e.mwp >= 20) {
114	    faktor *= 1.06;
115	    treiber.push("Ab 20 MWp: breiter Käuferkreis, Skaleneffekte bei Bau und Betrieb.");
116	  }
117	
118	  /* --- Vermarktung ---------------------------------------------------- */
119	  if (e.vermarktung === "eeg") {
120	    if (e.land !== "DE") {
121	      hinweise.push("EEG-Zuschlag gibt es nur in Deutschland – in Österreich entspricht dem die EAG-Marktprämie aus der Ausschreibung.");
122	    }
123	    if (pi >= idx("satzung") || bestand) {
124	      faktor *= 1.12;
125	      risikoStufe -= 1;
126	      treiber.push("Zuschlag gesichert: 20 Jahre Marktprämie als Erlösboden – bankfähig.");
127	    } else {
128	      hinweise.push("Ein Zuschlag setzt in der Regel Baurecht voraus – bitte Phase prüfen.");
129	    }
130	  } else if (e.vermarktung === "ppa") {
131	    faktor *= 1.1;
132	    risikoStufe -= 1;
133	    treiber.push("Unterschriebener PPA: planbare Erlöse, erleichtert die Finanzierung.");
134	  } else if (pi >= idx("satzung")) {
135	    hinweise.push(`Noch ohne Vermarktung: Zuletzt lagen EEG-Zuschläge um ${String(ERLOESE.eegFreiflaecheCt).replace(".", ",")} ct/kWh, PPA-Preise grob zwischen ${String(ERLOESE.ppaCt.min).replace(".", ",")} und ${String(ERLOESE.ppaCt.max).replace(".", ",")} ct/kWh.`);
136	  }
137	
138	  /* --- Land ------------------------------------------------------------ */
139	  if (e.land === "AT") {
140	    hinweise.push("Österreich: Flächenwidmung (z. B. Grünland-Photovoltaik) und Förderung nach EAG (Marktprämie bzw. Investitionszuschuss) prägen den Wert; ab bestimmten Größen ist eine UVP-Prüfung nötig.");
141	  } else if (e.land === "CH") {
142	    faktor *= 0.9;
143	    hinweise.push("Schweiz: kleiner Markt für Freiflächenprojekte, Bewilligung meist über Nutzungsplanung bzw. Solarexpress (alpine Anlagen) – Vergleichswerte sind rar, die Spanne ist unsicherer.");
144	  }
145	
146	  if (!bestand && pi < idx("aufstellung")) {
147	    hinweise.push("Frühe Phase: Viele Käufer zahlen gestaffelt – ein Teil bei Signing, der Rest bei Meilensteinen (Satzungsbeschluss, RTB).");
148	  }
149	  if (bestand) {
150	    hinweise.push("Bestandsanlage: Maßgeblich sind Erlöse, Restlaufzeit von Förderung/PPA, Pachtvertrag, technischer Zustand und Ertragshistorie – der Wert folgt dem Barwert der Cashflows.");
151	  }
152	
153	  const clamp = (v) => Math.max(0, v);
154	  const preisKwp = {
155	    min: clamp(min * faktor - abzug),
156	    max: clamp(max * faktor - abzug),
157	  };
158	  preisKwp.mittel = (preisKwp.min + preisKwp.max) / 2;
159	  const gesamt = { min: preisKwp.min * kwp, mittel: preisKwp.mittel * kwp, max: preisKwp.max * kwp };
160	
161	  // Vor Inbetriebnahme bleibt immer ein Rest-Risiko (Bau, Netz, Vermarktung)
162	  risikoStufe = Math.max(bestand ? 0 : 1, Math.min(5, risikoStufe));
163	  const RISIKO = ["sehr gering", "gering", "mittel", "mittel–hoch", "hoch", "sehr hoch"];
164	
165	  return {
166	    eingabe: e,
167	    phase,
168	    phaseIndex: pi,
169	    kwp,
170	    faktor,
171	    abzugKwp: abzug,
172	    preisKwp,
173	    gesamt,
174	    risiko: RISIKO[risikoStufe],
175	    risikoStufe,
176	    treiber,
177	    minderer,
178	    hinweise,
179	    monateBisRtb: phase.monateBisRtb,
180	    kaufpreisNull: preisKwp.max <= 0,
181	  };
182	}
183	
184	/* ------------------------------------------------------------------ */
185	/* Selbsttest: node src/lib/rechner/projektbewertung.js                */
186	/* ------------------------------------------------------------------ */
187	
188	export function selbsttest() {
189	  const fehler = [];
190	  const pruefe = (ok, text) => {
191	    if (!ok) fehler.push(text);
192	  };
193	  const neutral = bewerteProjekt({ mwp: 10, phase: "rtb", netz: "zusage", netzKm: 1, vermarktung: "keine", land: "DE" });
194	  pruefe(neutral.preisKwp.min === 60 && neutral.preisKwp.max === 130, "RTB neutral = PHASEN-Spanne");
195	  pruefe(neutral.gesamt.min === 600000, "10 MWp × 60 €/kWp = 600.000 €");
196	
197	  for (let i = 1; i < PHASEN.length; i++) {
198	    const a = bewerteProjekt({ phase: PHASEN[i - 1].id, netz: "zusage", netzKm: 1 });
199	    const b = bewerteProjekt({ phase: PHASEN[i].id, netz: "zusage", netzKm: 1 });
200	    pruefe(b.preisKwp.mittel >= a.preisKwp.mittel * 0.9, `Wert steigt tendenziell mit der Phase (${PHASEN[i].id})`);
201	  }
202	  const ohneNetz = bewerteProjekt({ phase: "rtb", netz: "offen" });
203	  pruefe(ohneNetz.preisKwp.mittel < neutral.preisKwp.mittel, "fehlende Netzanfrage mindert den Wert");
204	  const weit = bewerteProjekt({ phase: "rtb", netz: "zusage", netzKm: 6 });
205	  pruefe(weit.preisKwp.mittel < neutral.preisKwp.mittel && weit.minderer.length > 0, "lange Trasse mindert den Wert");
206	  const klein = bewerteProjekt({ mwp: 2, phase: "rtb", netz: "zusage", netzKm: 1 });
207	  pruefe(klein.preisKwp.mittel < neutral.preisKwp.mittel, "kleine Projekte je kWp günstiger");
208	  const eeg = bewerteProjekt({ phase: "rtb", netz: "zusage", netzKm: 1, vermarktung: "eeg" });
209	  pruefe(eeg.preisKwp.mittel > neutral.preisKwp.mittel && eeg.risikoStufe <= neutral.risikoStufe, "Zuschlag erhöht Wert, senkt Risiko");
210	  const extrem = bewerteProjekt({ mwp: 1, phase: "flaeche", netz: "offen", netzKm: 20 });
211	  pruefe(extrem.preisKwp.min >= 0 && extrem.preisKwp.max >= 0, "nie negative Preise");
212	  pruefe(bewerteProjekt({ phase: "cod" }).preisKwp.min > 300, "Bestand bewertet als Anlage");
213	  return fehler;
214	}
215	
216	if (typeof process !== "undefined" && process.argv?.[1] && /projektbewertung\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
217	  const f = selbsttest();
218	  for (const p of PHASEN) {
219	    const r = bewerteProjekt({ phase: p.id });
220	    console.log(p.id.padEnd(12), Math.round(r.preisKwp.min), "–", Math.round(r.preisKwp.max), "€/kWp", r.risiko);
221	  }
222	  if (f.length) {
223	    console.error("FEHLER:\n- " + f.join("\n- "));
224	    process.exit(1);
225	  }
226	  console.log("Selbsttest projektbewertung.js: alle Prüfungen bestanden.");
227	}
228	// src/lib/rechner/bestandsanlage.js
229	//
230	// Bewertung laufender PV-Anlagen (Zweitmarkt) nach dem Ertragswert- bzw.
231	// DCF-Verfahren. Reine Logik ohne React; Standardwerte aus
232	// src/lib/invest/markt.js (BESTAND, ERLOESE, PHASEN, FREIFLAECHE).
233	//
234	// Methodik (bewusst einfach und offen gelegt):
235	//  - Cashflow je Kalenderjahr ab BESTAND.bewertungsjahr, unverschuldet,
236	//    vor Ertragsteuern
237	//  - Erzeugung: gemessener Ø-Ertrag der letzten Jahre (kWh/kWp) × kWp,
238	//    Degradation ab heute
239	//  - Förderphase bis Ende des Jahres IBN + Förderdauer: feste Vergütung oder
240	//    Marktprämie (anzulegender Wert wirkt als Untergrenze)
241	//  - danach Marktwert Solar (Merchant) mit Steigerung, abzüglich
242	//    Direktvermarktungskosten
243	//  - Laufzeit bis Ende der technischen Nutzungsdauer – oder bis Ende des
244	//    Pacht-/Dachvertrags, wenn keine Verlängerung gesichert ist
245	//  - Kosten: Betriebskosten und Pacht (mit Inflation), optional
246	//    Wechselrichtertausch, Rückbau-Rücklage im letzten Jahr
247	//  - Ertragswert = Barwert der Cashflows; Spanne: Diskont ±1 Prozentpunkt
248	//    kombiniert mit Ertrag ±5 %
249	
250	import { BESTAND, ERLOESE, FREIFLAECHE, PACHT, PHASEN, REGIONEN, regionById, npv, irr } from "../invest/markt.js";
251	
252	export const PHASE_BESTAND = PHASEN.find((p) => p.id === "cod");
253	
254	/** Grober Richtwert der Vergütung nach IBN-Jahr (nur Vorbelegung) */
255	export function verguetungRichtwert(ibnJahr) {
256	  return (BESTAND.verguetungRichtwerte.find((v) => ibnJahr <= v.bis) || BESTAND.verguetungRichtwerte.at(-1)).ct;
257	}
258	
259	export const STANDARD = {
260	  kwp: 2000,
261	  ibnJahr: 2012,
262	  modell: "fest", // fest | marktpraemie
263	  verguetungCt: verguetungRichtwert(2012),
264	  foerderJahre: BESTAND.foerderJahre,
265	  ertragKwhKwp: 1000,
266	  regionId: "de-sued",
267	  typ: "freiflaeche", // freiflaeche | dach (nur für den Prognosevergleich)
268	  degradation: BESTAND.degradation,
269	  opexKwp: BESTAND.opexProKwp,
270	  pachtJahr: 6000,
271	  pachtEndeJahr: 2042,
272	  pachtVerlaengerbar: true,
273	  nutzungsdauer: BESTAND.nutzungsdauer,
274	  wrTausch: true,
275	  wrJahr: 2028,
276	  wrProKwp: BESTAND.wechselrichterProKwp.mittel,
277	  diskont: BESTAND.diskont.standard,
278	  merchantCt: ERLOESE.merchantCt,
279	  merchantSteigerung: ERLOESE.merchantSteigerung,
280	  rueckbau: true,
281	  kaufpreis: 0,
282	};
283	
284	/** Cashflow-Reihe und Kennzahlen für eine Eingabe */
285	export function rechneBestand(eingabe = {}) {
286	  const e = { ...STANDARD, ...eingabe };
287	  const start = BESTAND.bewertungsjahr;
288	  const alter = start - e.ibnJahr; // Betriebsjahre bis zum Bewertungsjahr
289	  const foerderEnde = e.ibnJahr + e.foerderJahre; // letztes Kalenderjahr mit Förderung (DE: IBN-Jahr + 20)
290	  const technischEnde = e.ibnJahr + e.nutzungsdauer;
291	  const ende = e.pachtVerlaengerbar ? technischEnde : Math.min(technischEnde, e.pachtEndeJahr);
292	  const restJahre = Math.max(0, ende - start + 1);
293	  const foerderRest = Math.max(0, Math.min(foerderEnde, ende) - start + 1);
294	
295	  const jahre = [];
296	  for (let i = 0; i < restJahre; i++) {
297	    const jahr = start + i;
298	    const t = i + 1;
299	    const kwh = e.kwp * e.ertragKwhKwp * Math.pow(1 - e.degradation, i);
300	    const marktCt = e.merchantCt * Math.pow(1 + e.merchantSteigerung, i);
301	    const gefoerdert = jahr <= foerderEnde;
302	    const preisCt = gefoerdert ? (e.modell === "marktpraemie" ? Math.max(e.verguetungCt, marktCt) : e.verguetungCt) : marktCt - BESTAND.direktvermarktungCt;
303	    const erloes = (kwh * preisCt) / 100;
304	    const opex = e.kwp * e.opexKwp * Math.pow(1 + FREIFLAECHE.inflation, i);
305	    const pacht = e.pachtJahr * Math.pow(1 + PACHT.indexierung, i);
306	    const wr = e.wrTausch && jahr === e.wrJahr ? e.kwp * e.wrProKwp : 0;
307	    const rueckbau = e.rueckbau && i === restJahre - 1 ? e.kwp * FREIFLAECHE.rueckbauProKwp : 0;
308	    const cf = erloes - opex - pacht - wr - rueckbau;
309	    jahre.push({ jahr, t, kwh, preisCt, gefoerdert, erloes, opex, pacht, wr, rueckbau, cf });
310	  }
311	
312	  const cfs = [0, ...jahre.map((j) => j.cf)];
313	  const wert = npv(e.diskont, cfs);
314	  const wertBei = (diskont, ertragFaktor) =>
315	    npv(diskont, [0, ...jahre.map((j) => j.cf + (j.erloes * (ertragFaktor - 1)))]);
316	  const spanne = {
317	    min: wertBei(e.diskont + 0.01, 0.95),
318	    max: wertBei(Math.max(e.diskont - 0.01, 0.001), 1.05),
319	  };
320	
321	  // Barwert-Anteil der Förderphase
322	  const bwFoerder = jahre.filter((j) => j.gefoerdert).reduce((s, j) => s + j.cf / Math.pow(1 + e.diskont, j.t), 0);
323	
324	  // Prognosevergleich: Ertrag laut Region (Freifläche optimal bzw. Dach) im heutigen Alter
325	  const region = regionById(e.regionId);
326	  const typFaktor = e.typ === "dach" ? 0.93 : 1;
327	  const prognose = region.ertrag * typFaktor * Math.pow(1 - e.degradation, Math.max(alter, 0));
328	  const performance = prognose > 0 ? e.ertragKwhKwp / prognose : null;
329	
330	  const wertProKwp = e.kwp > 0 ? wert / e.kwp : 0;
331	  const band = PHASE_BESTAND.preisProKwp;
332	  const einordnung = wertProKwp < band.min ? "unter" : wertProKwp > band.max ? "ueber" : "in";
333	
334	  const kaufIrr = e.kaufpreis > 0 ? irr([-e.kaufpreis, ...jahre.map((j) => j.cf)], -0.3, 1) : null;
335	
336	  return {
337	    eingabe: e,
338	    start,
339	    alter,
340	    foerderEnde,
341	    technischEnde,
342	    ende,
343	    restJahre,
344	    foerderRest,
345	    jahre,
346	    wert,
347	    wertProKwp,
348	    spanne,
349	    spanneProKwp: { min: spanne.min / e.kwp, max: spanne.max / e.kwp },
350	    anteilFoerderung: wert > 0 ? bwFoerder / wert : null,
351	    summeCf: jahre.reduce((s, j) => s + j.cf, 0),
352	    erloesJahr1: jahre[0]?.erloes || 0,
353	    cfJahr1: jahre[0]?.cf || 0,
354	    prognose,
355	    performance,
356	    einordnung,
357	    band,
358	    kaufIrr,
359	  };
360	}
361	
362	/**
363	 * Sensitivität: Wert je kWp bei verändertem Diskontsatz (Zeilen, Prozent-
364	 * punkte) und Marktpreis nach Förderende (Spalten, relativ).
365	 */
366	export function sensitivitaet(eingabe = {}, schritteDiskont = [-0.015, -0.0075, 0, 0.0075, 0.015], schrittePreis = [-0.3, -0.15, 0, 0.15, 0.3]) {
367	  const e = { ...STANDARD, ...eingabe };
368	  return schritteDiskont.map((dd) => ({
369	    diskont: dd,
370	    wertDiskont: e.diskont + dd,
371	    zellen: schrittePreis.map((dp) => {
372	      const r = rechneBestand({ ...e, diskont: Math.max(e.diskont + dd, 0.001), merchantCt: e.merchantCt * (1 + dp) });
373	      return { preis: dp, wertProKwp: r.wertProKwp };
374	    }),
375	  }));
376	}
377	
378	/** Tornado: Wirkung einzelner Annahmen auf den Ertragswert (€) */
379	export function tornado(eingabe = {}) {
380	  const e = { ...STANDARD, ...eingabe };
381	  const basis = rechneBestand(e).wert;
382	  const faelle = [
383	    { id: "ertrag", label: "Ertrag ±10 %", tief: { ertragKwhKwp: e.ertragKwhKwp * 0.9 }, hoch: { ertragKwhKwp: e.ertragKwhKwp * 1.1 } },
384	    { id: "diskont", label: "Diskontsatz ±1 Pp.", tief: { diskont: e.diskont + 0.01 }, hoch: { diskont: Math.max(e.diskont - 0.01, 0.001) } },
385	    { id: "markt", label: "Marktpreis nach Förderung ±25 %", tief: { merchantCt: e.merchantCt * 0.75 }, hoch: { merchantCt: e.merchantCt * 1.25 } },
386	    { id: "opex", label: "Betriebskosten ±20 %", tief: { opexKwp: e.opexKwp * 1.2 }, hoch: { opexKwp: e.opexKwp * 0.8 } },
387	    { id: "laufzeit", label: "Nutzungsdauer ±5 Jahre", tief: { nutzungsdauer: e.nutzungsdauer - 5 }, hoch: { nutzungsdauer: e.nutzungsdauer + 5 } },
